ALTER TABLE runs ADD COLUMN execution_profile TEXT NOT NULL DEFAULT 'reference';
ALTER TABLE runs ADD COLUMN content_mode TEXT NOT NULL DEFAULT 'local';
ALTER TABLE runs ADD COLUMN learning_mode TEXT NOT NULL DEFAULT 'skip';
ALTER TABLE runs ADD COLUMN initial_snapshot_hash TEXT NOT NULL DEFAULT '';
ALTER TABLE runs ADD COLUMN config_json TEXT NOT NULL DEFAULT '{}';
ALTER TABLE runs ADD COLUMN created_by TEXT;
CREATE TABLE run_grants(run_id TEXT NOT NULL REFERENCES runs(run_id), principal_id TEXT NOT NULL, PRIMARY KEY(run_id,principal_id));
CREATE TABLE active_runs(session_id TEXT PRIMARY KEY REFERENCES sessions(session_id), run_id TEXT NOT NULL REFERENCES runs(run_id));
INSERT INTO active_runs SELECT session_id,run_id FROM runs WHERE rowid IN (SELECT MAX(rowid) FROM runs GROUP BY session_id);
ALTER TABLE assets ADD COLUMN job_id TEXT;
ALTER TABLE assets ADD COLUMN purpose TEXT NOT NULL DEFAULT 'product_media';
UPDATE assets SET purpose='learning_report' WHERE kind='document' AND visibility='internal';
CREATE TABLE asset_jobs(run_id TEXT NOT NULL,asset_id TEXT NOT NULL,job_id TEXT NOT NULL,PRIMARY KEY(run_id,asset_id,job_id),FOREIGN KEY(run_id,asset_id) REFERENCES assets(run_id,asset_id),FOREIGN KEY(run_id,job_id) REFERENCES content_jobs(run_id,job_id));
ALTER TABLE content_jobs ADD COLUMN retry_scope TEXT NOT NULL DEFAULT 'all';
ALTER TABLE content_jobs ADD COLUMN source_content_id TEXT;
UPDATE content_jobs SET source_content_id=(SELECT parent_content_id FROM content_versions WHERE content_versions.run_id=content_jobs.run_id AND content_id=json_extract(content_jobs.output_content_ids_json,'$[0]'));
INSERT OR IGNORE INTO asset_jobs SELECT j.run_id,a.asset_id,j.job_id FROM content_jobs j JOIN content_versions cv ON cv.run_id=j.run_id AND cv.content_id=json_extract(j.output_content_ids_json,'$[0]') JOIN assets a ON a.run_id=j.run_id AND (a.asset_id=cv.cover_asset_id OR a.asset_id IN (SELECT json_extract(value,'$.asset_id') FROM json_each(cv.cover_options_json)) OR a.asset_id IN (SELECT value FROM json_each(j.input_asset_ids_json)));
ALTER TABLE operations ADD COLUMN claimed_by TEXT;
ALTER TABLE learning_handoffs ADD COLUMN version INTEGER NOT NULL DEFAULT 1;
ALTER TABLE learning_handoffs ADD COLUMN lease_until TEXT;
ALTER TABLE learning_handoffs ADD COLUMN auto_advance INTEGER NOT NULL DEFAULT 0;
ALTER TABLE learning_handoffs ADD COLUMN attempt INTEGER NOT NULL DEFAULT 1;
ALTER TABLE learning_handoffs ADD COLUMN summary_shop_id TEXT NOT NULL DEFAULT 'D';
ALTER TABLE learning_handoffs ADD COLUMN presentation_json TEXT NOT NULL DEFAULT '{}';
ALTER TABLE learning_handoffs ADD COLUMN receipt_id TEXT;
ALTER TABLE learning_handoffs ADD COLUMN receipt_hash TEXT;
UPDATE learning_handoffs SET lease_until=strftime('%Y-%m-%dT%H:%M:%f+00:00',created_at,'+60 seconds') WHERE status IN ('pending','running');
ALTER TABLE comparison_groups ADD COLUMN status TEXT NOT NULL DEFAULT 'ready';
ALTER TABLE comparison_groups ADD COLUMN version INTEGER NOT NULL DEFAULT 1;
ALTER TABLE comparison_groups ADD COLUMN config_hash TEXT NOT NULL DEFAULT '';
CREATE TABLE external_event_receipts(run_id TEXT NOT NULL REFERENCES runs(run_id),principal_id TEXT NOT NULL,external_id TEXT NOT NULL,request_hash TEXT NOT NULL,seq INTEGER NOT NULL,PRIMARY KEY(run_id,principal_id,external_id));
CREATE TABLE restore_receipts(run_id TEXT NOT NULL,source_content_id TEXT NOT NULL,previous_content_id TEXT NOT NULL,result_content_id TEXT NOT NULL,decision_id TEXT NOT NULL,request_hash TEXT NOT NULL,result_json TEXT NOT NULL,PRIMARY KEY(run_id,source_content_id,previous_content_id));
CREATE INDEX operations_pending ON operations(status,lease_until);
CREATE INDEX asset_jobs_job ON asset_jobs(run_id,job_id);
CREATE TABLE run_artifacts(run_id TEXT NOT NULL REFERENCES runs(run_id),kind TEXT NOT NULL,asset_id TEXT NOT NULL,sha256 TEXT NOT NULL,metadata_json TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(run_id,kind),FOREIGN KEY(run_id,asset_id) REFERENCES assets(run_id,asset_id));
UPDATE runs SET schema_version=2;
